syntax:
SELECT COUNT(*), MIN(столбец), MAX(столбец)
FROM таблица
WHERE условие;

example:
SELECT COUNT(*), MIN(reported_at), MAX(reported_at)
FROM incidents
WHERE district = 'Шахтный';

SELECT camera_id, ROUND(AVG(confidence), 2) AS avg_conf
FROM plate_reads
GROUP BY camera_id;

syntax:
SELECT выражение AS имя
FROM таблица
ORDER BY имя;

SELECT столбец, COUNT(*), MIN(…), MAX(…)
FROM таблица
GROUP BY столбец;

example:
SELECT district, COUNT(*) AS calls, MAX(reported_at) AS last_call
FROM incidents
GROUP BY district;

SELECT COUNT(DISTINCT plate)
FROM plate_reads
WHERE camera_id = 12;

syntax:
SELECT MIN(temp_c)
FROM heat_readings
WHERE temp_c <> -999;

example:
SELECT flat_id, ts, temp_c
FROM heat_readings
WHERE temp_c = -999;
